import React, { useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import './Meeting.css';

/**
 * Meeting component to handle the video meeting interface.
 *
 * @param {MediaStream} stream The media stream of the user.
 * @param {Function} handleMuteUnmute Function to mute or unmute the user's microphone.
 * @param {Function} handleOpenCloseCamera Function to open or close the user's camera.
 */
function Meeting({ stream, handleMuteUnmute, handleOpenCloseCamera, socket }) {
  // Reference for the user's video element
  const userVideo = useRef();

  // Hook to navigate between routes
  const navigate = useNavigate();

  // Effect to set the user's video stream
  useEffect(() => {
    if (stream) {
      // Assign the passed media stream to the video element
      userVideo.current.srcObject = stream;
    }
  }, [stream]);

  /**
   * Function to handle leaving the meeting.
   * Navigates the user back to the root route.
   */
  const handleLeave = () => {
    if (socket) {
      socket.emit('left'); // Emit 'leave' event when leaving the meeting
    }
    navigate('/');
  };

  return (
    <div className="App">
      <main>
        {/* Video elements for displaying local and remote videos */}
        <video ref={userVideo} id="localVideo" autoPlay muted></video>
        <video id="remoteVideo" autoPlay></video>
        <div>
          {/* Buttons to control mute/unmute and camera, and to leave the call */}
          <button onClick={() => handleMuteUnmute(stream)}>Mute/Unmute</button>
          <button onClick={() => handleOpenCloseCamera(userVideo)}>Open/Close Camera</button>
          <button id="callButton" onClick={handleLeave}>Leave</button>
        </div>
      </main>
    </div>
  );
}

export default Meeting;
